<script>
document.addEventListener('DOMContentLoaded',function(){
  var box=document.getElementById('atvChat');
  if(!box)return;
  var people={
    seller:{name:<?= json_encode((string)($p['seller_username']??'Seller')) ?>,icon:<?= json_encode((string)($p['seller_icon']??'')) ?>,label:'Seller'},
    client:{name:<?= json_encode((string)($p['client_username']??'Buyer')) ?>,icon:<?= json_encode((string)($p['client_icon']??$p['client_avatar']??'')) ?>,label:'Buyer'},
    admin:{name:'Admin',icon:<?= json_encode(defined('ICON_URL')?ICON_URL.'/03ce541a1f4bf8b06c924439ffcc8173.png':'') ?>,label:'Admin'}
  };
  function esc(v){var d=document.createElement('div');d.textContent=String(v||'');return d.innerHTML}
  function enhance(){
    box.querySelectorAll('.atvMsg:not([data-account-chat])').forEach(function(msg){
      msg.dataset.accountChat='1';
      var role=['seller','client','admin','system'].find(function(r){return msg.classList.contains(r)})||'seller';
      var avatar=msg.querySelector('.atvAvatar'),bubble=msg.querySelector('.atvBubble');
      if(role==='system'){if(avatar)avatar.remove();return}
      var person=people[role]||people.seller;
      if(avatar&&person.icon)avatar.innerHTML='<img src="'+esc(person.icon)+'" alt="">';
      if(avatar&&bubble){
        var head=document.createElement('div');head.className='atvMsgHead';
        var name=document.createElement('div');name.className='atvName';
        name.innerHTML=esc(person.name)+' <span class="atvRole '+role+'">'+esc(person.label)+'</span>';
        head.appendChild(avatar);head.appendChild(name);msg.insertBefore(head,bubble);
      }
      var stamp=msg.querySelector('.atvStamp');
      if(stamp&&stamp.textContent.indexOf('·')!==-1)stamp.textContent=stamp.textContent.split('·').slice(1).join('·').trim();
    });
  }
  new MutationObserver(enhance).observe(box,{childList:true,subtree:true});enhance();
});
</script>
